const incoming = $input.first().json;
const event = incoming.body ?? incoming;
if (incoming.headers) {
  const expectedSecret = $vars.AGF_CALENDAR_WEBHOOK_SECRET;
  const receivedSecret = incoming.headers['x-agf-webhook-secret'] || incoming.headers['X-AGF-Webhook-Secret'];
  if (!expectedSecret || receivedSecret !== expectedSecret) throw new Error('Webhook de teste do Calendar não autorizado.');
}
const summary = event.summary ?? event.event_title ?? '';
const rawDescription = event.description ?? '';
const description = rawDescription
  .replace(/<br\s*\/?\s*>/gi, '\n')
  .replace(/<\/(?:p|div|li|tr)>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/gi, '&')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&#39;/gi, "'")
  .replace(/&quot;/gi, '"')
  .replace(/\r/g, '');
const startsAt = event.start?.dateTime ?? event.starts_at;
const endsAt = event.end?.dateTime ?? event.ends_at;
if (!event.id && !event.provider_event_id) throw new Error('Evento sem identificador.');
if (!startsAt && String(event.status ?? '').toLowerCase() !== 'cancelled') return [];
const attendeeList = Array.isArray(event.attendees) ? event.attendees : [];
const guests = attendeeList.filter((attendee) => !attendee.organizer && !attendee.self);
const mainGuest = guests[0] ?? {};
const companyMatch = description.match(/(?:^|\n)\s*(?:Nome\s+da\s+Empresa|Empresa|Company(?:\s+Name)?)\s*(?::\s*|\n+\s*)([^\n]+)/i);
const appointmentGuestMatch = summary.match(/\(([^()]+)\)\s*$/);
const namedSummaryMatch = summary.match(/\b(?:with|com)\s+(.+)$/i);
const guestName = event.guest_name ?? mainGuest.displayName ?? appointmentGuestMatch?.[1]?.trim() ?? namedSummaryMatch?.[1]?.trim() ?? null;
const meetingUrl = event.hangoutLink ?? event.conferenceData?.entryPoints?.find((item) => item.entryPointType === 'video')?.uri ?? event.meeting_url ?? null;
return [{ json: { payload: {
  provider_event_id: event.id ?? event.provider_event_id,
  status: event.status ?? 'confirmed',
  event_title: summary,
  starts_at: startsAt ?? null,
  ends_at: endsAt ?? null,
  meeting_url: meetingUrl,
  booking_link: event.htmlLink ?? event.booking_link ?? null,
  guest_email: event.guest_email ?? mainGuest.email ?? null,
  guest_name: guestName,
  company_answer: event.company_answer ?? companyMatch?.[1]?.trim() ?? null,
  additional_participant_mentioned: guests.length > 1,
  additional_participant_note: guests.length > 1 ? guests.slice(1).map((guest) => guest.displayName || guest.email).filter(Boolean).join(', ') : null,
  raw_event: event
}} }];
